// Preserve stable lesson/progress IDs while enriching the first six stops.
GERS.splice(0, 6, ...TRAVELER_GERS);

const checked = new Map(SITUATIONS.flatMap((s) => s.phrases.map((p) => [p.en, p.mn] as const)));
const lc = (s: string) => transliterate(s).toLowerCase();

function build(g: GerSpec, s: Spec, n: number): Lesson {
  const ph = s.p.map((r) => {
    const [en, mn] = typeof r === "string" ? [r, checked.get(r)] : r;
    if (!mn) throw new Error(`Unknown checked phrase: ${en}`);
    return { en, mn };
  });
  return {
    id: `${g.id}-${n}`,
    title: s.t,
    subtitle: g.name,
    emoji: g.emoji,
    kind: "words",
    ger: g.id,
    items: ph.map((p, i) => ({ id: `p${i + 1}`, show: p.mn, say: lc(p.mn), hint: "", emoji: g.emoji, trick: "", meaning: p.en })),
    dialogue: s.d.map((l) => (typeof l === "number" ? { mn: ph[l].mn, en: ph[l].en } : { mn: l[0], en: l[1] })),
    note: s.n ? { text: s.n[0], source: s.n[1] } : undefined,
  };
}

export const CURRICULUM: Lesson[] = GERS.flatMap((g) => g.lessons.map((s, i) => build(g, s, i + 1)));
export const CURRICULUM_IDS = new Set(CURRICULUM.map((l) => l.id));
